# Check if there's a way to make the class test fail while still testing backward compat
import sys
sys.path.insert(0, '/root/repo')

from funcy import reraise

# Test with tuple of errors
@reraise((ValueError, KeyError), TypeError)
def bad_func():
    raise ValueError("test")

try:
    bad_func()
except TypeError as te:
    print(f"Caught TypeError: '{te}'")
    print(f"__cause__: {te.__cause__}")
